using System.Collections.Generic;using Janseon.Core.Data;using Janseon.Data.Validation;
namespace Janseon.Data.Repositories { public sealed class UnitRoleCatalogRepository:IReadOnlyUnitRoleCatalog { readonly Dictionary<string,UnitRoleCatalogItem> byId=new Dictionary<string,UnitRoleCatalogItem>(System.StringComparer.Ordinal);public IReadOnlyList<UnitRoleCatalogItem> All{get;}public UnitRoleCatalogRepository(GameDataCatalogIndex i){All=i.UnitRoles;foreach(var x in All)byId.Add(x.StableId,x);}public bool TryGet(string id,out UnitRoleCatalogItem x)=>byId.TryGetValue(id??string.Empty,out x);}}
